#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-only
"""Check generated bytes and the forwarding wrapper in the linked AArch64 ELF."""
import hashlib
import json
import re
import struct
import sys
from pathlib import Path

PROGRAM_ID = 0x00FF4E5348414D01
FORWARD = '_ZNK3ams2sf4hipc13ServerSession14ForwardRequestERKNS0_4cmif22ServiceDispatchContextE'


def require(condition, message):
    if not condition:
        raise ValueError(message)


def u32(data, offset):
    return struct.unpack_from('<I', data, offset)[0]


def verify_return_nro(data):
    require(len(data) >= 0x80 and data[0x10:0x14] == b'NRO0', 'return NRO header')
    image_size = u32(data, 0x18)
    require(0x80 <= image_size <= len(data) - 0x38, 'return NRO image bounds')
    for entry in (0x20, 0x28, 0x30):
        offset, size = struct.unpack_from('<II', data, entry)
        require(offset <= image_size and size <= image_size - offset, 'return NRO segment bounds')
    require(data[image_size:image_size + 8] == b'ASET\0\0\0\0', 'return NRO assets')
    for entry in (8, 24, 40):
        offset, size = struct.unpack_from('<QQ', data, image_size + entry)
        if size:
            require(0x38 <= offset <= len(data) - image_size, 'return NRO asset offset')
            require(size <= len(data) - image_size - offset, 'return NRO asset bounds')
    nacp_offset, nacp_size = struct.unpack_from('<QQ', data, image_size + 24)
    require(nacp_size == 0x4000, 'return NRO NACP size')
    title = data[image_size + nacp_offset:image_size + nacp_offset + 0x200].split(b'\0', 1)[0]
    require(title == b'Return to HOME', 'unexpected return NRO title')


def pfs(data):
    require(data[:4] == b'PFS0', 'PFS0 magic')
    count, strings_size = struct.unpack_from('<II', data, 4)
    require(count == 2, 'ExeFS must contain only main and main.npdm')
    strings = 16 + count * 24
    base = strings + strings_size
    require(base <= len(data), 'PFS header bounds')
    files = {}
    for i in range(count):
        offset, size, name_at, reserved = struct.unpack_from('<QQII', data, 16 + i * 24)
        require(reserved == 0 and name_at < strings_size, 'PFS entry')
        end = data.find(b'\0', strings + name_at, base)
        require(end >= 0 and offset + size <= len(data) - base, 'PFS name/data bounds')
        name = data[strings + name_at:end].decode('ascii')
        require(name not in files, 'PFS duplicate')
        files[name] = data[base + offset:base + offset + size]
    require(set(files) == {'main', 'main.npdm'}, 'unexpected ExeFS files')
    return files


def verify(elf_path, nsp_path, disassembly_path):
    elf = elf_path.read_bytes()
    require(elf[:6] == b'\x7fELF\x02\x01', 'ELF64 little-endian')
    require(struct.unpack_from('<H', elf, 18)[0] == 183, 'AArch64 machine')
    entry, phoff = struct.unpack_from('<QQ', elf, 24)
    phsize, phcount = struct.unpack_from('<HH', elf, 54)
    require(phsize == 56 and phoff + phsize * phcount <= len(elf), 'ELF program header bounds')
    executable_entry = False
    for i in range(phcount):
        typ, flags, offset, address, _, size, memory, _ = struct.unpack_from('<IIQQQQQQ', elf, phoff + i * phsize)
        if typ == 1:
            require(offset + size <= len(elf) and memory >= size, 'ELF segment bounds')
            executable_entry |= bool(flags & 1 and address <= entry < address + memory)
    require(executable_entry, 'entry inside executable LOAD segment')

    files = pfs(nsp_path.read_bytes())
    nso, npdm = files['main'], files['main.npdm']
    require(nso[:4] == b'NSO0' and len(nso) >= 0x100, 'NSO0 header')
    flags = u32(nso, 0xC)
    for i in range(3):
        offset = u32(nso, 0x10 + i * 16)
        size = u32(nso, 0x18 + i * 16)
        disk_size = u32(nso, 0x60 + i * 4) if flags & (1 << i) else size
        require(offset >= 0x100 and offset + disk_size <= len(nso), 'NSO segment bounds')
    require(npdm[:4] == b'META', 'NPDM META')
    aci, aci_size, acid, acid_size = struct.unpack_from('<IIII', npdm, 0x70)
    require(aci + aci_size <= len(npdm) and acid + acid_size <= len(npdm), 'NPDM bounds')
    require(npdm[aci:aci + 4] == b'ACI0', 'ACI0 magic')
    require(struct.unpack_from('<Q', npdm, aci + 0x10)[0] == PROGRAM_ID, 'ACI0 program ID')
    magic = acid + 0x200
    require(npdm[magic:magic + 4] == b'ACID', 'ACID magic')
    require(struct.unpack_from('<QQ', npdm, magic + 0x10) == (PROGRAM_ID, PROGRAM_ID), 'ACID ID range')

    owner = None
    calls = []
    allocator_calls = []
    functions = set()
    for line in disassembly_path.read_text().splitlines():
        label = re.match(r'^([0-9a-f]+) <([^>]+)>:', line)
        if label:
            owner = label[2]
            functions.add(owner)
        branch = re.search(r'\s(?:bl|b)\s+[0-9a-f]+ <([^>]+)>', line)
        if branch and branch[1] in (FORWARD, '__wrap_' + FORWARD):
            calls.append((owner, branch[1]))
        if branch:
            allocator_calls.append((owner, branch[1]))
    for source, target in (('_malloc_r', 'malloc'), ('_free_r', 'free'),
                           ('_calloc_r', 'calloc'), ('_realloc_r', 'realloc'),
                           ('_memalign_r', 'aligned_alloc')):
        require((source, target) in allocator_calls, f'{source} must use Stratosphere {target}')
    require('_sbrk_r' not in functions, 'newlib sbrk allocator must not be linked')
    require(FORWARD in functions and '__wrap_' + FORWARD in functions, 'real/wrapper symbols')
    real_calls = [source for source, target in calls if target == FORWARD]
    require(real_calls == ['__wrap_' + FORWARD], 'exactly one real forward call, only from wrapper')
    wrapped = [source for source, target in calls if target == '__wrap_' + FORWARD]
    require(len(wrapped) >= 2 and all(s != '__wrap_' + FORWARD for s in wrapped), 'root/domain framework forwarding must use wrapper')
    nro_connected = any('worker' in source and 'launch_nro' in target for source, target in allocator_calls)
    require(nro_connected, 'launch worker must call the requested NRO consumer')
    titles_calls = ['nsListApplicationRecord', 'nsIsAnyApplicationEntityInstalled',
                    'nsListApplicationContentMetaStatus', 'nsGetApplicationControlData',
                    'ncmContentMetaDatabaseGetLatestContentMetaKey', 'ncmContentMetaDatabaseListContentInfo', 'ncmContentStorageHas']
    titles_connected = all(name in functions for name in titles_calls) and any(name.startswith('_ZN6nshome6titles5startE') for name in functions)
    require(titles_connected, 'installed title worker and NS/NCM evidence calls must be linked')
    receipt = {
        'program_id': f'{PROGRAM_ID:016X}',
        'checks': ['ELF64 AArch64', 'executable entry', 'PFS0', 'NSO bounds', 'NPDM ID', 'linked forwarding branches', 'unified newlib allocation'],
        'wrapped_calls': wrapped,
        'sha256': {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in (elf_path, nsp_path)},
        'hardware_tested': False,
        'launch_bridge_connected': '_ZN8observer6launch5startEv' in functions,
        'launch_flow_hardware_tested': False,
        'nro_launch_connected': nro_connected,
        'installed_titles_connected': titles_connected,
        'installed_titles_hardware_tested': False,
        'launch_commands': ['gamestart', 'launch'] if '_ZN8observer6launch5startEv' in functions else [],
    }
    (nsp_path.parent / 'verification.json').write_text(json.dumps(receipt, indent=2) + '\n')
    print(json.dumps(receipt, indent=2))


if __name__ == '__main__':
    verify(*(Path(arg) for arg in sys.argv[1:]))
